  // a loop that doesn't click: the end of the loop is crossfaded (equal power) into what comes before its start
  function nbLoopFade(buf, ls, le) {
    const sr = buf.sampleRate, a = Math.round(ls * sr), b = Math.min(buf.length - 1, Math.round(le * sr)), n = Math.min(Math.round(0.25 * sr), Math.floor(a * 0.9), Math.floor((b - a) * 0.4));
    if (n < 64) return;
    for (let c = 0; c < buf.numberOfChannels; c++) {
      const d = buf.getChannelData(c);
      for (let i = 0; i < n; i++) { const w = i / n, x = b - n + i, y = a - n + i; d[x] = d[x] * Math.cos(w * Math.PI / 2) + d[y] * Math.sin(w * Math.PI / 2); }
    }
  }
  // where the note really starts (a decoder may leave the MP3's encoder delay in front of it)
  function nbLead(buf) {
    const d = buf.getChannelData(0), n = Math.min(d.length, Math.round(buf.sampleRate * 0.3)); let pk = 0;
    for (let i = 0; i < n; i++) { const v = Math.abs(d[i]); if (v > pk) pk = v; }
    const th = Math.max(1e-4, pk * 0.02); let i = 0; while (i < n && Math.abs(d[i]) < th) i++;
    return Math.max(0, i / buf.sampleRate - 0.004);
  }
